/* PC-TWINS knowledge map — renders window.KMAP_DATA (generated by gen_data.py). */
(() => {
  "use strict";

  const DATA = window.KMAP_DATA;
  const SVG_NS = "http://www.w3.org/2000/svg";

  if (!DATA || !Array.isArray(DATA.modules)) {
    const panel = document.getElementById("panel");
    if (panel) {
      panel.innerHTML = '<p class="kmap-empty">未能加载 data.js：请先运行 <code>python gen_data.py</code>。</p>';
    }
    return;
  }

  const modules = DATA.modules;
  const byId = new Map(modules.map((m) => [m.id, m]));

  const state = {
    selected: null
  };

  /* ------------------------------------------------------------------ helpers */

  const $ = (sel) => document.querySelector(sel);

  const esc = (s) => String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

  const svg = (tag, attrs = {}) => {
    const node = document.createElementNS(SVG_NS, tag);
    Object.entries(attrs).forEach(([k, v]) => node.setAttribute(k, v));
    return node;
  };

  const closure = (id, edgesOf) => {
    const out = new Set();
    const stack = [...edgesOf(byId.get(id))];
    while (stack.length) {
      const next = stack.pop();
      if (!out.has(next)) {
        out.add(next);
        stack.push(...edgesOf(byId.get(next)));
      }
    }
    return out;
  };
  // Typeset $...$ / $$...$$ inside a freshly updated node (KaTeX auto-render).
  const MATH_OPTS = {
    delimiters: [
      { left: "$$", right: "$$", display: true },
      { left: "$", right: "$", display: false }
    ],
    throwOnError: false
  };
  const renderMath = (node) => {
    if (node && typeof window.renderMathInElement === "function") {
      window.renderMathInElement(node, MATH_OPTS);
    }
  };

  const ancestorsOf = (id) => closure(id, (m) => m.prereqs);
  const descendantsOf = (id) => closure(id, (m) => m.successors);

  let layout = null;

  // Approximate rendered width in "CJK character" units (Latin glyphs are narrower).
  const textUnits = (t) => [...t].reduce((w, ch) => w + (/[\u2E80-\uFFEF]/.test(ch) ? 1 : 0.58), 0);

  const wrapName = (name, maxUnits) => {
    if (textUnits(name) <= maxUnits) return [name];
    const spaces = [...name.matchAll(/ /g)].map((mt) => mt.index);
    if (spaces.length) {
      const mid = name.length / 2;
      const cut = spaces.reduce((best, i) => (Math.abs(i - mid) < Math.abs(best - mid) ? i : best), spaces[0]);
      return [name.slice(0, cut), name.slice(cut + 1)];
    }
    const chars = [...name];
    const half = textUnits(name) / 2;
    let acc = 0;
    let cut = 1;
    for (let i = 0; i < chars.length; i += 1) {
      acc += textUnits(chars[i]);
      if (acc >= half) { cut = i + 1; break; }
    }
    return [chars.slice(0, cut).join(""), chars.slice(cut).join("")];
  };

  const computeLayout = (width) => {
    const layers = [...new Set(modules.map((m) => m.layer))].sort((a, b) => a - b);
    const rows = layers.map((L) => modules.filter((m) => m.layer === L));
    const maxPerRow = Math.max(...rows.map((r) => r.length));
    const pad = 6;
    const gap = width < 420 ? 8 : 14;
    const nodeW = Math.min(196, (width - 2 * pad - (maxPerRow - 1) * gap) / maxPerRow);
    const compact = nodeW < 140;
    const nodeH = compact ? 56 : 52;
    const labelH = 18;
    const rowGap = compact ? 26 : 30;
    const pos = new Map();
    let y = 4;

    rows.forEach((row, ri) => {
      // Order nodes by the mean x of their prerequisites to reduce crossings.
      if (ri > 0) {
        row.sort((a, b) => {
          const bary = (m) => {
            const xs = m.prereqs.map((p) => pos.get(p).cx);
            return xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : width / 2;
          };
          return bary(a) - bary(b);
        });
      }
      const rowW = row.length * nodeW + (row.length - 1) * gap;
      const x0 = (width - rowW) / 2;
      const top = y + labelH;
      row.forEach((m, i) => {
        const x = x0 + i * (nodeW + gap);
        pos.set(m.id, { x, y: top, w: nodeW, h: nodeH, cx: x + nodeW / 2 });
      });
      y = top + nodeH + rowGap;
    });

    return { width, height: y - rowGap + 8, pos, rows, layers, nodeW, nodeH, labelH, compact };
  };

  const renderGraph = () => {
    const host = $("#graph");
    const width = Math.max(280, Math.floor(host.clientWidth - 16));
    layout = computeLayout(width);
    const { pos, rows, layers, height, compact } = layout;
    const root = svg("svg", {
      viewBox: `0 0 ${width} ${height}`,
      width: String(width),
      height: String(height),
      role: "group",
      "aria-label": "模块依赖图"
    });

    const defs = svg("defs");
    const marker = svg("marker", {
      id: "kmap-arrow", viewBox: "0 0 8 8", refX: "7", refY: "4",
      markerWidth: "7", markerHeight: "7", orient: "auto-start-reverse"
    });
    marker.appendChild(svg("path", { d: "M0 0 L8 4 L0 8 z", class: "kmap-arrow" }));
    defs.appendChild(marker);
    root.appendChild(defs);

    // edges (drawn first, under the nodes)
    const edgeLayer = svg("g", { class: "kmap-edges" });
    modules.forEach((m) => {
      m.prereqs.forEach((p) => {
        const a = pos.get(p);
        const b = pos.get(m.id);
        const x1 = a.cx;
        const y1 = a.y + a.h;
        const x2 = b.cx + (m.prereqs.length > 1 ? (m.prereqs.indexOf(p) - (m.prereqs.length - 1) / 2) * 12 : 0);
        const y2 = b.y - 2;
        const dy = Math.max(18, (y2 - y1) * 0.5);
        const path = svg("path", {
          d: `M${x1.toFixed(1)} ${y1} C${x1.toFixed(1)} ${y1 + dy} ${x2.toFixed(1)} ${y2 - dy} ${x2.toFixed(1)} ${y2}`,
          class: "kmap-edge",
          "marker-end": "url(#kmap-arrow)",
          "data-from": p,
          "data-to": m.id
        });
        edgeLayer.appendChild(path);
      });
    });
    root.appendChild(edgeLayer);

    // layer labels (above edges, with a halo so crossing edges stay readable)
    rows.forEach((row, ri) => {
      const p = pos.get(row[0].id);
      const label = svg("text", { x: "6", y: String(p.y - 6), class: "kmap-layer-label" });
      const L = layers[ri];
      label.textContent = `第 ${L} 层 · ${DATA.layers[String(L)] || ""}`;
      root.appendChild(label);
    });

    // nodes
    const fontPx = compact ? 12 : 13;
    const maxUnits = (layout.nodeW - 18) / fontPx;
    modules.forEach((m) => {
      const p = pos.get(m.id);
      const g = svg("g", {
        class: "kmap-node",
        tabindex: "0",
        role: "button",
        "data-id": m.id,
        "aria-label": `${m.id} ${m.zh}`
      });
      g.appendChild(svg("rect", { class: "kmap-node-box", x: p.x, y: p.y, width: p.w, height: p.h, rx: "9" }));
      const title = svg("title");
      title.textContent = `${m.id} ${m.zh}（第 ${m.layer} 层）`;
      g.appendChild(title);
      const idText = svg("text", { class: "kmap-node-id", x: p.x + 9, y: p.y + 15 });
      idText.textContent = m.id;
      g.appendChild(idText);
      const lines = wrapName(m.short, maxUnits);
      lines.forEach((line, i) => {
        const t = svg("text", {
          class: "kmap-node-name",
          x: p.x + 9,
          y: p.y + (lines.length === 1 ? 35 : 30 + i * 14.5)
        });
        if (compact) t.setAttribute("style", "font-size:12px");
        t.textContent = line;
        g.appendChild(t);
      });
      g.addEventListener("click", () => select(m.id, { scrollPanel: true }));
      g.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          select(m.id, { scrollPanel: true });
        }
      });
      root.appendChild(g);
    });

    host.replaceChildren(root);
    updateGraph();
  };

  const updateGraph = () => {
    if (!layout) return;
    const sel = state.selected;
    const anc = sel ? ancestorsOf(sel) : new Set();
    const desc = sel ? descendantsOf(sel) : new Set();

    document.querySelectorAll(".kmap-node").forEach((g) => {
      const id = g.dataset.id;
      g.classList.toggle("is-sel", id === sel);
      g.classList.toggle("is-pre", anc.has(id));
      g.classList.toggle("is-post", desc.has(id));
      g.classList.toggle("is-far", Boolean(sel) && (anc.has(id) || desc.has(id))
        && !byId.get(sel).prereqs.includes(id) && !byId.get(sel).successors.includes(id));
      g.classList.toggle("is-dim", Boolean(sel) && id !== sel && !anc.has(id) && !desc.has(id));
      g.setAttribute("aria-pressed", String(id === sel));
    });

    document.querySelectorAll(".kmap-edge").forEach((e) => {
      const from = e.dataset.from;
      const to = e.dataset.to;
      const pre = Boolean(sel) && anc.has(from) && (to === sel || anc.has(to));
      const post = Boolean(sel) && desc.has(to) && (from === sel || desc.has(from));
      e.classList.toggle("is-pre", pre);
      e.classList.toggle("is-post", post);
      e.classList.toggle("is-dim", Boolean(sel) && !pre && !post);
      e.classList.toggle("is-far", (pre || post) && from !== sel && to !== sel);
    });
  };

  /* ------------------------------------------------------------------- panel */

  const citation = (ref) => {
    const vol = ref.volume ? ` <b>${esc(ref.volume)}</b>` : "";
    const pages = ref.pages ? `, ${esc(ref.pages)}` : "";
    return `${esc(ref.authors)}. <span class="kmap-cite-title">${esc(ref.title)}</span>. `
      + `<span class="kmap-cite-venue"><i>${esc(ref.venue)}</i>${vol}${pages} (${esc(ref.year)})</span>`;
  };

  const renderPanel = () => {
    const panel = $("#panel");
    const m = byId.get(state.selected);
    if (!m) return;

    const chips = (ids, cls) => ids.length
      ? ids.map((id) => `<button type="button" class="kmap-chip-link ${cls}" data-goto="${id}">${id} ${esc(byId.get(id).short)}</button>`).join("")
      : '<span class="kmap-links-label">无</span>';

    const concepts = m.concepts.map((c) => `<li>${esc(c)}</li>`).join("");
    const results = m.results.map((r) => `<li class="kmap-result"><p class="kmap-result-name">${esc(r.name)}</p>`
      + `<div class="kmap-formula">$$${esc(r.tex)}$$</div>`
      + (r.note ? `<p class="kmap-result-note">${esc(r.note)}</p>` : "") + "</li>").join("");

    const readings = m.readings.map((r) => {
      const ref = DATA.refs[r.ref];
      const links = ref.links.map((l) => `<a class="action-link" href="${esc(l.href)}" target="_blank" rel="noopener">${esc(l.label)}</a>`).join("");
      const unverified = ref.verified ? "" : '<span class="kmap-tag kmap-tag-unverified">未能核实</span>';
      const note = ref.note ? `<p class="kmap-reading-note">${esc(ref.note)}</p>` : "";
      return `<li class="kmap-reading">`
        + `<div class="kmap-reading-tags"><span class="kmap-tag kmap-tag-${r.priority}">${r.priority}</span>`
        + `<span class="kmap-tag">${r.type}</span>${unverified}</div>`
        + `<p class="kmap-cite">${citation(ref)}</p>`
        + `<p class="kmap-reading-part">${esc(r.part)}</p>`
        + `<p class="kmap-reading-why">${esc(r.why)}</p>${note}`
        + `<div class="kmap-reading-links">${links}</div></li>`;
    }).join("");

    const terms = m.terms.map((t) => `<div class="kmap-term"><dt>${esc(t.zh)}<span class="kmap-term-en">${esc(t.en)}</span></dt>`
      + `<dd>${esc(t.definition)}</dd></div>`).join("");

    panel.innerHTML = `
      <div class="kmap-panel-head">
        <span class="kmap-panel-id">${m.id}</span><h3>${esc(m.zh)}</h3>
        <p class="kmap-panel-en">${esc(m.en)}</p>
        <ul class="kmap-meta">
          <li>第 ${m.layer} 层</li>
          <li>教材第 ${m.chapters.join("、")} 章</li>
        </ul>
      </div>
      <p class="kmap-why">${esc(m.why)}</p>
      <p class="kmap-links"><span class="kmap-links-label">前置：</span>${chips(m.prereqs, "is-pre")}<br>
        <span class="kmap-links-label">后续：</span>${chips(m.successors, "is-post")}</p>
      <h4>核心概念</h4>
      <ul class="kmap-concepts">${concepts}</ul>
      <h4>关键结果与公式 <span class="kmap-count">${m.results.length} 条</span></h4>
      <ul class="kmap-results">${results}</ul>
      <h4>推荐阅读 <span class="kmap-count">${m.readings.length} 项</span></h4>
      <ul class="kmap-readings">${readings}</ul>
      <h4>关键术语 <span class="kmap-count">${m.terms.length} 个</span></h4>
      <dl class="kmap-terms">${terms}</dl>`;
    renderMath(panel);
  };

  const select = (id, { scrollPanel = false, updateHash = true } = {}) => {
    if (!byId.has(id)) return;
    state.selected = id;
    renderPanel();
    updateGraph();
    const panel = $("#panel");
    panel.scrollTop = 0;
    if (updateHash) {
      try {
        window.history.replaceState(null, "", `#${id}`);
      } catch {}
    }
    if (scrollPanel && window.matchMedia("(max-width: 980px)").matches) {
      panel.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  /* ---------------------------------------------------------------- glossary */

  const allTerms = modules.flatMap((m) => m.terms.map((t) => ({ ...t, module: m.id })))
    .sort((a, b) => a.en.localeCompare(b.en, "en", { sensitivity: "base" }));

  const highlightPlain = (text, q) => {
    const safe = esc(text);
    if (!q) return safe;
    const i = text.toLowerCase().indexOf(q);
    if (i < 0) return safe;
    return esc(text.slice(0, i)) + "<mark>" + esc(text.slice(i, i + q.length)) + "</mark>" + esc(text.slice(i + q.length));
  };

  // Highlight matches only outside $...$ so KaTeX still sees intact TeX.
  const highlight = (text, q) => text.split(/(\$[^$]+\$)/)
    .map((part, i) => (i % 2 ? esc(part) : highlightPlain(part, q))).join("");

  const renderGlossary = () => {
    const q = ($("#term-search").value || "").trim().toLowerCase();
    const hits = allTerms.filter((t) => !q
      || t.zh.toLowerCase().includes(q)
      || t.en.toLowerCase().includes(q)
      || t.definition.toLowerCase().includes(q));
    const list = $("#glossary-list");
    list.innerHTML = hits.length
      ? hits.map((t) => `<div class="kmap-term"><dt>${highlight(t.zh, q)}<span class="kmap-term-en">${highlight(t.en, q)}</span>`
        + `<button type="button" class="kmap-chip-link" data-goto="${t.module}" data-scroll="map">${t.module}</button></dt>`
        + `<dd>${highlight(t.definition, q)}</dd></div>`).join("")
      : '<p class="kmap-glossary-empty">没有匹配的术语。</p>';
    renderMath(list);
    $("#term-count").textContent = q ? `${hits.length} / ${allTerms.length} 个术语` : `共 ${allTerms.length} 个术语`;
  };

  /* ------------------------------------------------------------------ wiring */

  const setupEvents = () => {
    document.addEventListener("click", (event) => {
      const go = event.target.closest("[data-goto]");
      if (!go) return;
      select(go.dataset.goto, { scrollPanel: true });
      if (go.dataset.scroll === "map") {
        const target = window.matchMedia("(max-width: 980px)").matches ? $("#panel") : $("#map");
        target.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    });

    $("#term-search").addEventListener("input", renderGlossary);

    let resizeTimer = 0;
    let lastWidth = $("#graph").clientWidth;
    window.addEventListener("resize", () => {
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(() => {
        const w = $("#graph").clientWidth;
        if (w !== lastWidth) {
          lastWidth = w;
          renderGraph();
        }
      }, 120);
    });

    window.addEventListener("hashchange", () => {
      const id = window.location.hash.slice(1);
      if (byId.has(id)) select(id, { updateHash: false });
    });
  };

  // Shared with the homepage: theme toggle, reading progress, back-to-top.
  const setupChrome = () => {
    const toggle = document.querySelector(".theme-toggle");
    if (toggle) {
      const apply = (theme, persist) => {
        const isDark = theme === "dark";
        document.documentElement.dataset.theme = isDark ? "dark" : "light";
        toggle.setAttribute("aria-pressed", String(isDark));
        const label = isDark ? "切换到浅色模式" : "切换到深色模式";
        toggle.setAttribute("aria-label", label);
        toggle.setAttribute("title", label);
        if (persist) {
          try {
            window.localStorage.setItem("yunze-theme", isDark ? "dark" : "light");
          } catch {}
        }
      };
      apply(document.documentElement.dataset.theme || "light", false);
      toggle.addEventListener("click", () => apply(document.documentElement.dataset.theme === "dark" ? "light" : "dark", true));
    }

    const progress = document.querySelector(".reading-progress");
    const backToTop = document.querySelector(".back-to-top");
    const onScroll = () => {
      const range = document.documentElement.scrollHeight - window.innerHeight;
      if (progress) progress.style.transform = `scaleX(${range > 0 ? Math.min(window.scrollY / range, 1) : 0})`;
      if (backToTop) backToTop.classList.toggle("is-visible", window.scrollY > 320);
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    if (backToTop) {
      backToTop.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));
    }
  };

  const init = () => {
    setupChrome();
    document.querySelector('[data-stat="modules"]').textContent = String(modules.length);
    document.querySelector('[data-stat="layers"]').textContent = String(new Set(modules.map((m) => m.layer)).size);
    document.querySelector('[data-stat="results"]').textContent = String(modules.reduce((n, m) => n + m.results.length, 0));
    document.querySelector('[data-stat="terms"]').textContent = String(allTerms.length);
    const gen = document.querySelector("[data-generated]");
    if (gen) gen.textContent = `数据生成于 ${DATA.generated}`;
    renderGraph();
    renderGlossary();
    setupEvents();
    const fromHash = window.location.hash.slice(1);
    select(byId.has(fromHash) ? fromHash : modules[0].id, { updateHash: false });
  };

  init();
})();
